pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 extraAmount) public {
        // Bound amounts to reasonable values to keep the test fast while leaving the domain wide
        depositAmount = bound(depositAmount, 1, 100 ether);
        extraAmount = bound(extraAmount, 0, 100 ether);
        // Ensure no overflow on total contract balance
        vm.assume(depositAmount + extraAmount <= 200 ether);

        // Send ether to the contract to simulate deposits
        address sender = makeAddr("sender");
        vm.deal(sender, depositAmount + extraAmount);
        vm.prank(sender);
        (bool sent,) = address(c).call{value: depositAmount}("");
        require(sent, "deposit failed");

        // Also send via sendMoney to ensure extra balance is present
        if (extraAmount > 0) {
            vm.prank(sender);
            c.sendMoney(address(c), extraAmount);
        }

        // Owner will call withdrawAll. Record owner's balance before and after.
        address owner = c.owner();
        uint256 ownerBalanceBefore = owner.balance;
        uint256 contractBalanceBefore = address(c).balance;

        vm.prank(owner);
        c.withdrawAll();

        uint256 ownerBalanceAfter = owner.balance;
        // The rule: owner's balance after withdrawAll equals owner's balance before plus the contract's full balance before
        // The bug: withdrawAll calls withdraw(0), so the owner receives nothing regardless of contract balance.
        // The reference correctly transfers the full contract balance.
        assertTrue(ownerBalanceAfter == ownerBalanceBefore + contractBalanceBefore);
    }
}

