pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 sendAmount, uint256 extra) public {
        // bound amounts to reasonable range to avoid overflow and keep balance manageable
        amount = bound(amount, 0, 100 ether);
        sendAmount = bound(sendAmount, 1, 50 ether);
        extra = bound(extra, 0, 50 ether);
        // ensure sendAmount <= amount so we have enough balance for sendMoney
        vm.assume(sendAmount <= amount);

        // deploy adversarial helper: a contract whose fallback always reverts
        Reverter reverter = new Reverter();

        // fund the contract and call sendMoney to a reverting target, which leaves the balance unchanged
        vm.deal(address(c), amount);
        vm.prank(c.owner());
        c.sendMoney(address(reverter), sendAmount);

        // now deposit extra ether via fallback so total balance = amount + extra
        if (extra > 0) {
            vm.deal(address(this), extra);
            (bool ok,) = address(c).call{value: extra}("");
            require(ok, "deposit failed");
        }

        uint256 balanceBefore = address(c).balance;
        uint256 withdrawAmount = sendAmount; // we try to withdraw the amount we attempted to send

        // owner withdraws withdrawAmount
        vm.prank(c.owner());
        try c.withdraw(withdrawAmount) { } catch { }

        uint256 balanceAfter = address(c).balance;
        // For the correct implementation, the withdrawn amount is withdrawAmount.
        // For the buggy implementation, the full balance is withdrawn (balanceBefore).
        // The rule: the withdrawn amount is exactly withdrawAmount.
        assertTrue(balanceBefore - balanceAfter == withdrawAmount);
    }
}

