import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 withdrawAmount, address target) public {
        // Restrict to plausible nonzero amounts and ensure withdraw doesn't exceed initial balance
        bound(amount, 1, address(c).balance);
        vm.assume(target != address(0) && target != address(c) && target != address(this));
        // Deploy an adversarial helper that reverts on receiving ETH
        Reverter reverter = new Reverter();
        // Fund the contract via fallback
        vm.deal(address(this), amount);
        (bool ok,) = address(c).call{value: amount}("");
        require(ok, "funding failed");
        // Send money to a reverting target, leaving balance intact but call fails
        vm.prank(c.owner());
        c.sendMoney(address(reverter), amount);
        // Bound withdrawAmount to something <= current balance
        uint256 balanceAfterSend = address(c).balance;
        withdrawAmount = bound(withdrawAmount, 1, balanceAfterSend);
        // Record owner balance before withdraw
        uint256 ownerBefore = c.owner().balance;
        // Owner withdraws
