pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Reverter reverter;

    function setUp() public {
        c = new C();
        reverter = new Reverter();
    }

    function testFuzz_property(uint256 initialBalance, uint256 sendValue, uint256 withdrawValue) public {
        // Keep values in a meaningful range
        vm.assume(initialBalance > 0);
        vm.assume(sendValue > 0);
        vm.assume(withdrawValue > 0);
        vm.assume(initialBalance <= address(c).balance || true); // dummy to avoid unused variable

        // Fund the contract with some ether
        vm.deal(address(this), initialBalance);
        (bool funded,) = address(c).call{value: initialBalance}("");
        require(funded, "funding failed");

        uint256 balanceBeforeSend = address(c).balance;

        // Send money to a reverting target, trapping the excess balance
        vm.prank(c.owner());
        c.sendMoney(address(reverter), sendValue);

        uint256 balanceAfterSend = address(c).balance;
        // After a failing sendMoney, the contract balance should be unchanged
        assertEq(balanceAfterSend, balanceBeforeSend, "balance must not change on failed send");

        uint256 ownerBalanceBeforeWithdraw = c.owner().balance;

        // Now owner withdraws a value <= current balance
        vm.prank(c.owner());
        c.withdraw(withdrawValue);

        uint256 contractBalanceAfterWithdraw = address(c).balance;
        uint256 ownerBalanceAfterWithdraw = c.owner().balance;

        // Reference rule: owner's balance increase is exactly withdrawValue
        // Buggy version: owner's balance increases by the full pre-withdraw balance
        assertEq(
            ownerBalanceAfterWithdraw - ownerBalanceBeforeWithdraw,
            withdrawValue,
            "owner received exactly withdrawValue"
        );
    }
}

