        // Owner sends some funds to attacker so that sendMoney call is made to a contract that reverts
        vm.deal(c.owner(), 1 ether);
        vm.prank(c.owner());
        c.sendMoney(address(attacker), 1 wei);

        // Now record balance before withdrawAll
        uint256 balanceBefore = address(c).balance;

        // The attacker's address is not needed for withdrawAll, but we need to ensure a previous sendMoney to a reverting contract was triggered,
        // because the mutant only differs for non-owner callers, and the reference restricts to owner only. For owner calls, both behave identically.
        // We test the invariant: after withdrawAll completes without reverting, the contract balance must be zero.
        // We try calling withdrawAll from a non-owner (fuzzed actor), which will revert in reference but succeed in mutant.
        vm.prank(actor);
        try c.withdrawAll() {
            // If it succeeded (only possible in mutant for actor != owner), assert the invariant
            assertEq(address(c).balance, 0, "Balance must be zero after successful withdrawAll");
        } catch {
            // In reference, only owner can call, so it reverts for non-owners. That's acceptable; no balance change expected.
            // But if it reverted, balance must remain unchanged.
            assertEq(address(c).balance, balanceBefore, "Balance must be unchanged after reverted withdrawAll");
        }
    }
