pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositCount, uint256 withdrawAmount) public {
        // Restrict depositCount to a reasonable range to avoid overflow of address(c).balance
        vm.assume(depositCount <= 10);
        // Require at least one deposit so there is something to withdraw
        vm.assume(depositCount >= 1);

        address donor = address(0x1234);
        vm.deal(donor, depositCount * 1 ether);

        // Perform the given number of deposits via the fallback function
        for (uint256 i = 0; i < depositCount; i++) {
            vm.prank(donor);
            (bool success,) = address(c).call{value: 1 ether}("");
            require(success, "deposit failed");
        }

        // Owner withdraws a strictly positive amount not exceeding the balance
        vm.assume(withdrawAmount > 0 && withdrawAmount <= depositCount * 1 ether);
        vm.prank(c.owner());
        c.withdraw(withdrawAmount);

        // After the withdraw, depositsCount must equal depositCount
        // (the number of fallback calls that succeeded before the withdraw)
        assertTrue(c.depositsCount() == depositCount);
    }
}

