pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositCountBefore, uint256 withdrawAmount) public {
        // Bound depositCountBefore to a reasonable number (>=1 to have deposits)
        depositCountBefore = bound(depositCountBefore, 1, 100);
        // Fund the owner
        vm.deal(address(this), 1000 ether);
        vm.prank(address(this));
        // Perform depositCountBefore deposits to trigger fallback and increment depositsCount
        for (uint256 i = 0; i < depositCountBefore; i++) {
