            require(ok, "deposit failed");
        }
        uint256 preDeposits = c.depositsCount();
        require(preDeposits == depositCountBefore, "setup invariant");

        // Bound withdrawAmount to be less than or equal to the contract's balance
        uint256 balanceBefore = address(c).balance;
        withdrawAmount = bound(withdrawAmount, 1, balanceBefore);
        vm.prank(address(this));
        c.withdraw(withdrawAmount);

        // After a successful withdraw, depositsCount must still equal the number of deposits made before
        uint256 postDeposits = c.depositsCount();
        assertTrue(postDeposits == preDeposits, "depositsCount changed after withdraw");
    }
}

